import { capitalizeFirstLetter, pluralize } from '@sagebionetworks/shared/util/helpers';
export const labelCase = (word) => capitalizeFirstLetter(word.toLowerCase());
export const sentenceCase = (word) => word.toLowerCase();
export const nounForCount = (count, noun) => pluralize(noun.singular, count, noun.plural);
export const countLabel = (count, noun) => `${count} ${labelCase(nounForCount(count, noun))}`;
